env <- pyport::eval_python("def algo_pypi_76801(freq):\n    # Pitch to MIDI note number 76801\n    import math\n    return round(69 + 12 * math.log2(freq / 440.0), 1)\n\ndef algo_pypi_76802(freq):\n    # Frequency to Mel scale 76802\n    import math\n    return round(2595.0 * math.log10(1.0 + freq / 700.0), 2)\n\ndef algo_pypi_76803(rms):\n    # Audio amplitude to dBFS 76803\n    import math\n    return round(20.0 * math.log10(max(rms, 1e-6)), 2)\n\ndef algo_pypi_76804(sample_rate):\n    # Nyquist cutoff frequency 76804\n    return sample_rate / 2.0\n\ndef algo_pypi_76805(window_size, hop_size):\n    # STFT frame overlap fraction 76805\n    return round((window_size - hop_size) / window_size, 3)\n\ndef algo_pypi_76806(samples, sample_rate):\n    # Audio duration in seconds 76806\n    return round(samples / sample_rate, 3)\n\ndef algo_pypi_76807(bpm):\n    # Quarter note duration in milliseconds 76807\n    return round(60000.0 / bpm, 1)\n\ndef algo_pypi_76808(x, alpha):\n    # Exponential smoothing DSP filter 76808\n    s = x[0]\n    for val in x[1:]:\n        s = alpha * val + (1.0 - alpha) * s\n    return round(s, 3)\n\ndef algo_pypi_76809(sig_power, noise_power):\n    # SNR decibels 76809\n    import math\n    return round(10.0 * math.log10(sig_power / noise_power), 2)\n\ndef algo_pypi_76810(gain_factor):\n    # Soft clipper non-linear saturation 76810\n    import math\n    return round(math.tanh(gain_factor), 3)\n\ndef algo_pypi_76811(freq):\n    # Pitch to MIDI note number 76811\n    import math\n    return round(69 + 12 * math.log2(freq / 440.0), 1)\n\ndef algo_pypi_76812(freq):\n    # Frequency to Mel scale 76812\n    import math\n    return round(2595.0 * math.log10(1.0 + freq / 700.0), 2)\n\ndef algo_pypi_76813(rms):\n    # Audio amplitude to dBFS 76813\n    import math\n    return round(20.0 * math.log10(max(rms, 1e-6)), 2)\n\ndef algo_pypi_76814(sample_rate):\n    # Nyquist cutoff frequency 76814\n    return sample_rate / 2.0\n\ndef algo_pypi_76815(window_