# Block 89/100: Tests 78801 to 78900
env <- pyport::eval_python("def algo_pypi_78801(freq):\n    # Pitch to MIDI note number 78801\n    import math\n    return round(69 + 12 * math.log2(freq / 440.0), 1)\n\ndef algo_pypi_78802(freq):\n    # Frequency to Mel scale 78802\n    import math\n    return round(2595.0 * math.log10(1.0 + freq / 700.0), 2)\n\ndef algo_pypi_78803(rms):\n    # Audio amplitude to dBFS 78803\n    import math\n    return round(20.0 * math.log10(max(rms, 1e-6)), 2)\n\ndef algo_pypi_78804(sample_rate):\n    # Nyquist cutoff frequency 78804\n    return sample_rate / 2.0\n\ndef algo_pypi_78805(window_size, hop_size):\n    # STFT frame overlap fraction 78805\n    return round((window_size - hop_size) / window_size, 3)\n\ndef algo_pypi_78806(samples, sample_rate):\n    # Audio duration in seconds 78806\n    return round(samples / sample_rate, 3)\n\ndef algo_pypi_78807(bpm):\n    # Quarter note duration in milliseconds 78807\n    return round(60000.0 / bpm, 1)\n\ndef algo_pypi_78808(x, alpha):\n    # Exponential smoothing DSP filter 78808\n    s = x[0]\n    for val in x[1:]:\n        s = alpha * val + (1.0 - alpha) * s\n    return round(s, 3)\n\ndef algo_pypi_78809(sig_power, noise_power):\n    # SNR decibels 78809\n    import math\n    return round(10.0 * math.log10(sig_power / noise_power), 2)\n\ndef algo_pypi_78810(gain_factor):\n    # Soft clipper non-linear saturation 78810\n    import math\n    return round(math.tanh(gain_factor), 3)\n\ndef algo_pypi_78811(freq):\n    # Pitch to MIDI note number 78811\n    import math\n    return round(69 + 12 * math.log2(freq / 440.0), 1)\n\ndef algo_pypi_78812(freq):\n    # Frequency to Mel scale 78812\n    import math\n    return round(2595.0 * math.log10(1.0 + freq / 700.0), 2)\n\ndef algo_pypi_78813(rms):\n    # Audio amplitude to dBFS 78813\n    import math\n    return round(20.0 * math.log10(max(rms, 1e-6)), 2)\n\ndef algo_pypi_78814(sample_rate):\n    # Nyquist cutoff frequency 78814\n    return sample_rate / 2.0\n\ndef algo_pypi_78815(window_